<?php
declare(strict_types=1);
require __DIR__.'/video-tags.php';
$base=['id'=>str_repeat('1',32),'team'=>6369,'tag_key'=>'scoring','scope'=>'moment','start_ms'=>24000,'end_ms'=>24000,'duration_ms'=>180000,'certainty'=>'observed','note'=>'Visible sequence','polarity'=>'present'];
$score=['component'=>'fuel','phase'=>'teleop','method'=>'counted','count_min'=>12,'count_max'=>12,'hub_state'=>'active','points_min'=>9999];
$in=$base+['scoring'=>$score];$s->save($in,1,$actor,null,'ip');$s->save($in,1,$actor,null,'ip');
$entry=array_values(array_filter($s->mine(1,$actor),fn($r)=>$r['id']===$base['id']))[0];
ok($entry['scoring']['points_min']===12,'server calculates points and ignores client point claims');
ok($entry['review_state']==='contributed','scoring data has no approval queue');
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>array_replace($score,['hub_state'=>'unknown'])]),$m);
ok($v['scoring']['points_min']===null,'unknown hub state does not invent points');
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>array_replace($score,['hub_state'=>'inactive'])]),$m);
ok($v['scoring']['points_max']===0,'inactive hub scores zero match points');
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>array_replace($score,['method'=>'estimated','count_min'=>8,'count_max'=>11])]),$m);
ok($v['scoring']['points_min']===8&&$v['scoring']['points_max']===11,'estimated scoring remains a range');
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>array_replace($score,['method'=>'unknown','count_min'=>null,'count_max'=>null])]),$m);
ok($v['scoring']['count_min']===null&&$v['scoring']['points_min']===null,'unknown is not converted to zero');
foreach([['count_min'=>-1],['count_max'=>11],['component'=>'fake'],['count_min'=>1.5],['method'=>'estimated']] as $change)rejects(fn()=>CommunityVideoTags::validate(array_replace($in,['scoring'=>array_replace($score,$change)]),$m),'reject invalid amount '.json_encode($change));
rejects(fn()=>CommunityVideoTags::validate(array_replace($in,['tag_key'=>'disabled']),$m),'amount only attaches to a scoring tag');
rejects(fn()=>CommunityVideoTags::validate(array_replace($in,['polarity'=>'absent']),$m),'counterexample cannot claim points');
$m25=array_replace($m,['match_key'=>'2025test_qm7']);
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>['component'=>'coral_l4','phase'=>'auto','method'=>'counted','count_min'=>2,'count_max'=>2]]),$m25);
ok($v['scoring']['points_max']===14&&$v['scoring']['season']===2025,'REEFSCAPE AUTO point values stay separate');
rejects(fn()=>CommunityVideoTags::validate($in,$m25),'REEFSCAPE rejects REBUILT components');
rejects(fn()=>CommunityVideoTags::validate($in,array_replace($m,['match_key'=>'2027test_qm7'])),'future game does not inherit old point values');
$v=CommunityVideoTags::validate(array_replace($in,['scoring'=>['component'=>'tower_l1','phase'=>'auto','method'=>'counted','count_min'=>1,'count_max'=>1]]),$m);
ok($v['scoring']['points_max']===null,'AUTO tower alliance cap prevents unsupported point attribution');
$corrected=array_replace($in,['id'=>str_repeat('2',32),'replaces_id'=>$base['id'],'scoring'=>array_replace($score,['count_min'=>13,'count_max'=>13])]);
rejects(fn()=>$s->save($corrected,1,$other,null,'ip'),'cannot correct another browser contribution');
$s->save($corrected,1,$actor,null,'ip');$s->save($corrected,1,$actor,null,'ip');
$all=$s->mine(1,$actor);$original=array_values(array_filter($all,fn($r)=>$r['id']===$base['id']))[0];
ok($original['review_state']==='withdrawn'&&$original['scoring']['count_min']===12,'correction preserves original evidence and withdraws it');
$export=array_map('community_scoring_decode',$s->training()->fetchAll(PDO::FETCH_ASSOC));
ok(count(array_filter($export,fn($r)=>$r['id']===$base['id']))===0,'replaced label excluded from active training set');
$active=array_values(array_filter($export,fn($r)=>$r['id']===$corrected['id']))[0];ok($active['scoring']['points_min']===13&&$active['replaces_id']===$base['id'],'corrected amount and lineage exported');
$s->withdraw($corrected['id'],$actor);
ok(!array_filter($s->training()->fetchAll(PDO::FETCH_ASSOC),fn($r)=>$r['id']===$corrected['id']),'undo excludes amount from future training');

$fixture=['key'=>$m['match_key'],'actual_time'=>100,'alliances'=>['red'=>['score'=>400,'team_keys'=>['frc6369','frc2689','frc127']],'blue'=>['score'=>300,'team_keys'=>['frc9128','frc11178','frc5414']]]];
$fetches=0;$shareService=new CommunityVideoTags($db,function($path)use(&$fetches,$fixture){$fetches++;return $fixture;});
$share=array_replace($base,['id'=>str_repeat('3',32),'scope'=>'match','start_ms'=>null,'end_ms'=>null,'certainty'=>'uncertain','scoring'=>['mode'=>'alliance_share','robot_points'=>80,'method'=>'estimated','alliance_score'=>9999,'share_percent'=>99]]);
$shareService->save($share,1,$actor,null,'ip');$shareService->save($share,1,$actor,null,'ip');
$entry=array_values(array_filter($shareService->mine(1,$actor),fn($r)=>$r['id']===$share['id']))[0];
ok($entry['scoring']['alliance_score']===400&&$entry['scoring']['share_percent']==20,'whole-match percent uses the full official alliance score');
ok($entry['scoring']['robot_points']===80&&$entry['start_ms']===null,'whole-match points do not invent action timestamps');
ok($fetches===1,'retry preserves the original alliance-score snapshot and is idempotent');
$invalid=array_replace($share,['id'=>str_repeat('4',32),'scoring'=>['mode'=>'alliance_share','robot_points'=>401,'method'=>'estimated']]);
rejects(fn()=>$shareService->save($invalid,1,$actor,null,'ip'),'robot estimate cannot exceed alliance final');
$noScore=community_scoring_alliance_totals($m,fn($path)=>array_replace($fixture,['actual_time'=>null]));ok($noScore===null,'unplayed match has no invented final score');
$wrong=$fixture;$wrong['alliances']['red']['team_keys'][0]='frc9999';ok(community_scoring_alliance_totals($m,fn($path)=>$wrong)===null,'official score must match the expected robot roster');
$changed=array_replace($share,['id'=>str_repeat('5',32),'replaces_id'=>$share['id'],'scoring'=>['mode'=>'alliance_share','robot_points'=>100,'method'=>'estimated']]);$shareService->save($changed,1,$actor,null,'ip');$shareService->save($changed,1,$actor,null,'ip');
$entry=array_values(array_filter($shareService->mine(1,$actor),fn($r)=>$r['id']===$changed['id']))[0];ok($entry['scoring']['share_percent']==25,'corrected whole-match contribution recalculates the percentage');
